/**
 * The section library: ready page sections in templates/library/sections, written in FlowCode's own React and
 * design-token CSS (templates/library/library.css). Each takes on a project's colors, fonts, spacing and corners
 * from its tokens. The Components page browses them; builds copy the ones a screen needs.
 */
export type SectionCategory = "navigation" | "hero" | "features" | "stats" | "pricing" | "testimonials" | "faq" | "cta" | "team" | "contact" | "newsletter" | "blog" | "footer" | "forms" | "tables" | "cards" | "dialogs" | "alerts" | "backgrounds" | "data" | "auth" | "wayfinding" | "homepages" | "landings" | "sites" | "apptemplates" | "commerce" | "neobrutal" | "kit";

export interface LibrarySection {
  /** File stem in templates/library/sections. */
  id: string;
  name: string;
  category: SectionCategory;
  description: string;
  /** Words a request or spec uses when this section fits. */
  tags: string[];
  /**
   * The kinds of screen or feature this pattern serves, in the words a PRD would use ("order history", "attendance",
   * "time off requests"). FlowCode matches the PRD's screens against them, and the library index shows them to agents.
   */
  useCases?: string[];
  /**
   * The jobs people do with it, in their own words ("decide on a request", "see what happened on a day"). FlowCode
   * matches them against what each planned screen is for (the user's intent), and agents see them in the library index.
   */
  jobs?: string[];
  /**
   * A specimen: every state of one component in a table, for people to look at and copy from. It is documentation,
   * not a piece of a product, so a build must never seed a screen with one - a "Brands" screen came out as a chip
   * state matrix with Wedding and Portrait in it, and the design step was then required to keep it there.
   */
  specimen?: boolean;
  /**
   * The catalog ID, which says the level: c. a component (c.button), p. a pattern of a few components, b. a block or
   * feature (a page section), t. a whole page template. Pieces made before these IDs have none yet.
   */
  ref?: string;
  /** How an agent uses it without reading its file: the import and the props, in one line. */
  usage?: string;
  /** A component's variants. One component, a prop picks the variant and the design tokens style it; each has its own ID. */
  variants?: Array<{ ref: string; look: string }>;
  /** What it is built from, by catalog ID. "Used by" is worked out from these. */
  uses?: string[];
  /** What it looks like, in a sentence. */
  look?: string;
  /** The design tokens that decide its look. Change these, not the piece. */
  tokens?: string[];
  /** Another component documented and exported by the same file (a radio beside the checkbox), with its own ID. */
  also?: Array<{ ref: string; usage?: string; variants?: Array<{ ref: string; look: string }>; look?: string; tokens?: string[] }>;
}

/** "tokens": a rule the design tokens carry (the focus ring, motion), documented by a sheet but not a component. */
export type LibraryLevel = "component" | "pattern" | "block" | "template" | "tokens";

/** A catalog ID's level, read from its prefix. */
export function levelOf(ref: string): LibraryLevel | undefined {
  return ({ c: "component", p: "pattern", b: "block", t: "template", tokens: "tokens" } as const)[ref.split(".")[0] as "c"];
}

/** "template": whole pages, built from the library's own pieces. "page": marketing and website sections. "app": the
 * pieces an app's own screens are made of. */
export type SectionGroup = "template" | "page" | "app";

